   807  static int check_pe64_bytes(const ut8 *buf, ut64 length) {
   808          int idx, ret = false;
   809          if (!buf || length <= 0x3d) {
   810                  return false;
   811          }
   812          idx = buf[0x3c] | (buf[0x3d]<<8);
   813          if (length >= idx + 0x20) {
   814                  if (!memcmp (buf, "MZ", 2) && !memcmp (buf+idx, "PE", 2) && !memcmp (buf+idx+0x18, "\x0b\x02", 2)) {
   815                          ret = true;
   816                  }
   817          }
   818          return ret;
   819  }
