   821  static bool r_bin_mdmp_init_pe_bins(struct r_bin_mdmp_obj *obj) {
   822          bool dup;
   823          ut64 paddr;
   824          struct minidump_module *module;
   825          struct Pe32_r_bin_mdmp_pe_bin *pe32_bin, *pe32_dup;
   826          struct Pe64_r_bin_mdmp_pe_bin *pe64_bin, *pe64_dup;
   827          RBuffer *buf;
   828          RListIter *it, *it_dup;
   829
   830          r_list_foreach (obj->streams.modules, it, module) {
   831                  /* Duplicate modules can appear in the MDMP module list,
   832                  ** filtering them out seems to be the correct behaviour */
   833                  if (!(paddr = r_bin_mdmp_get_paddr (obj, module->base_of_image))) {
   834                          continue;
   835                  }
   836                  int left = 0;
   837                  const ut8 *b = r_buf_get_at (obj->b, paddr, &left);
   838                  buf = r_buf_new_with_bytes (b, R_MIN (left, module->size_of_image));
   839                  dup = false;
   840                  if (check_pe32_bytes (buf->buf, module->size_of_image)) {
   841                          r_list_foreach(obj->pe32_bins, it_dup, pe32_dup) {
   842                                  if (pe32_dup->vaddr == module->base_of_image) {
   843                                          dup = true;
   844                                          continue;
   845                                  }
   846                          }
   847                          if (dup) {
   848                                  continue;
   849                          }
   850                          if (!(pe32_bin = R_NEW0 (struct Pe32_r_bin_mdmp_pe_bin))) {
   851                                  continue;
   852                          }
   853                          r_bin_mdmp_patch_pe_headers (buf);
   854                          pe32_bin->vaddr = module->base_of_image;
   855                          pe32_bin->paddr = paddr;
   856                          pe32_bin->bin = Pe32_r_bin_pe_new_buf (buf, 0);
   857
   858                          r_list_append (obj->pe32_bins, pe32_bin);
   859                  } else if (check_pe64_bytes (buf->buf, module->size_of_image)) {
   860                          r_list_foreach(obj->pe64_bins, it_dup, pe64_dup) {
   861                                  if (pe64_dup->vaddr == module->base_of_image) {
   862                                          dup = true;
   863                                          continue;
   864                                  }
   865                          }
   866                          if (dup) {
   867                                  continue;
   868                          }
   869                          if (!(pe64_bin = R_NEW0 (struct Pe64_r_bin_mdmp_pe_bin))) {
   870                                  continue;
   925
   926          fail |= (!(obj->pe32_bins = r_list_newf (r_bin_mdmp_free_pe32_bin)));
   927          fail |= (!(obj->pe64_bins = r_list_newf (r_bin_mdmp_free_pe64_bin)));
   928
   929          if (fail) {
   930                  r_bin_mdmp_free (obj);
   931                  return NULL;
   932          }
   933
   934          if (!r_buf_set_bytes (obj->b, buf->buf, buf->length)) {
   935                  r_bin_mdmp_free (obj);
   936                  return NULL;
   937          }
   938
   939          if (!r_bin_mdmp_init (obj)) {
   940                  r_bin_mdmp_free (obj);
   941                  return NULL;
   942          }
   943
   944          return obj;
   945  }
